const request = require('request');
const { Webhooks } = require('@qasymphony/pulse-sdk');

exports.handler = function ({ event: body, constants, triggers }, context, callback) {
    function emitEvent(name, payload) {
        let t = triggers.find(t => t.name === name);
        return t && new Webhooks().invoke(t, payload);
    }

    const token = constants.GitHubToken;
    const repo = constants.GitHubRepo;
    const eventType = constants.GitHubEventType || 'run-tests';
    const apiBase = (constants.GitHubAPIURL || 'https://api.github.com').replace(/\/+$/, '');

    if (!token || !repo) {
        console.log('[ERROR] Missing GitHub configuration (GitHubToken / GitHubRepo)');
        emitEvent('ChatOpsEvent', { message: '[ERROR] GitHub Actions trigger config incomplete' });
        return;
    }

    const url = apiBase + '/repos/' + repo + '/dispatches';
    console.log('[INFO] Dispatching GitHub Actions for ' + repo + ' via ' + apiBase + ' (event_type: ' + eventType + ')');

    request({
        url: url,
        method: 'POST',
        headers: {
            'Authorization': 'Bearer ' + token,
            'Accept': 'application/vnd.github+json',
            'X-GitHub-Api-Version': '2022-11-28',
            // GitHub's API rejects requests without a User-Agent header.
            'User-Agent': 'qTest-Pulse',
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            event_type: eventType,
            client_payload: {
                source: 'qTest Scenario',
                scenarioId: body && body.id,
                triggeredAt: new Date().toISOString()
            }
        })
    }, function (err, res, responseBody) {
        if (err) {
            console.log('[ERROR] GitHub dispatch failed:', err);
            emitEvent('ChatOpsEvent', { message: '[ERROR] GitHub Actions trigger failed: ' + err });
            return;
        }

        // The dispatches API returns 204 No Content on success.
        if (res.statusCode === 204) {
            console.log('[SUCCESS] GitHub Actions workflow dispatched');
            emitEvent('ChatOpsEvent', { message: '[SUCCESS] GitHub Actions triggered (event_type: ' + eventType + ')' });
        } else {
            console.log('[ERROR] GitHub returned status: ' + res.statusCode + ' body: ' + responseBody);
            emitEvent('ChatOpsEvent', { message: '[ERROR] GitHub Actions trigger failed. Status: ' + res.statusCode + ' ' + responseBody });
        }
    });
};

const request = require('request');

exports.handler = function ({ event: body, constants, triggers }, context, callback) {
    const message = body.message || JSON.stringify(body);
    const webhook = constants.ChatOpsWebhook;

    if (!webhook) {
        console.log('[WARN] ChatOpsWebhook not configured, skipping notification');
        return;
    }

    request({
        uri: webhook,
        method: 'POST',
        json: { text: message, mrkdwn: true }
    }, function (err) {
        if (err) {
            console.log('[ERROR] Slack send failed:', err);
        } else {
            console.log('[INFO] Slack message sent');
        }
    });
};

const { Webhooks } = require('@qasymphony/pulse-sdk');

exports.handler = function ({ event: body, constants, triggers }, context, callback) {
    function emitEvent(name, payload) {
        let t = triggers.find(t => t.name === name);
        return t && new Webhooks().invoke(t, payload);
    }

    // Fall back to Pulse constants when the payload doesn't carry the IDs
    // (e.g. the FetchReportFromGitHub / direct-webhook paths).
    var projectId = body.projectId || constants.QTEST_PROJECT_ID;
    var cycleId = body.testcycle || constants.QTEST_TEST_CYCLE_ID;
    var testResults = [];

    try {
        if (body.result) {
            var decoded = Buffer.from(body.result, 'base64').toString('utf-8');
            testResults = JSON.parse(decoded);
        }
    } catch (e) {
        console.log('[ERROR] Failed to parse results:', e.message);
        emitEvent('ChatOpsEvent', { message: '[ERROR] Invalid test results: ' + e.message });
        return;
    }

    var testLogs = [];
    var passed = 0;
    var failed = 0;
    var skipped = 0;

    testResults.forEach(function (feature) {
        var featureName = feature.name || 'Unknown Feature';
        var featureUri = feature.uri || '';

        if (!feature.elements) {
            return;
        }

        feature.elements.forEach(function (scenario) {
            if (!scenario.name) scenario.name = 'Unnamed Scenario';

            var scenarioStatus = 'passed';
            var stepLogs = [];
            var stepOrder = 0;
            var stepNames = [];
            var attachments = [];

            if (!scenario.steps) return;

            scenario.steps.forEach(function (step) {
                var name = step.name || 'Unknown Step';
                var keyword = step.keyword || '';
                stepNames.push(keyword + name);

                var status = 'passed';
                var actual = keyword + name;

                if (!step.result) {
                    status = 'skipped';
                    if (scenarioStatus !== 'failed') scenarioStatus = 'skipped';
                } else {
                    status = step.result.status || 'passed';
                    if (status === 'failed') {
                        scenarioStatus = 'failed';
                        actual = step.result.error_message || 'Step failed';
                    } else if (status === 'skipped' || status === 'pending') {
                        status = 'skipped';
                        if (scenarioStatus !== 'failed') scenarioStatus = 'skipped';
                    } else if (status === 'undefined') {
                        scenarioStatus = 'failed';
                        status = 'failed';
                        actual = 'Step definition not found';
                    }
                }

                if (step.embeddings && Array.isArray(step.embeddings)) {
                    step.embeddings.forEach(function (emb, i) {
                        attachments.push({
                            name: name + ' Attachment ' + (i + 1),
                            content_type: emb.mime_type || 'application/octet-stream',
                            data: emb.data
                        });
                    });
                }

                stepLogs.push({
                    order: stepOrder++,
                    description: keyword + name,
                    expected_result: (step.match && step.match.location) ? step.match.location : keyword + name,
                    actual_result: actual,
                    status: status,
                    keyword: keyword
                });
            });

            if (scenarioStatus === 'passed') passed++;
            else if (scenarioStatus === 'failed') failed++;
            else skipped++;

            testLogs.push({
                exe_start_date: new Date().toISOString(),
                exe_end_date: new Date().toISOString(),
                module_names: [featureName],
                name: scenario.name,
                automation_content: featureUri + '#' + scenario.name,
                attachments: attachments,
                description: stepNames.join('<br/>'),
                status: scenarioStatus,
                test_step_logs: stepLogs,
                featureName: featureName
            });
        });
    });

    var total = passed + failed + skipped;
    console.log('[INFO] Formatted: Total=' + total + ' Passed=' + passed + ' Failed=' + failed + ' Skipped=' + skipped);
    emitEvent('ChatOpsEvent', {
        message: 'Test Summary: ' + total + ' total, ' + passed + ' passed, ' + failed + ' failed, ' + skipped + ' skipped'
    });

    emitEvent('UploadQTestResults', {
        projectId: projectId,
        testcycle: cycleId,
        logs: testLogs,
        summary: { total: total, passed: passed, failed: failed, skipped: skipped }
    });
};

const request = require('request');
const { Webhooks } = require('@qasymphony/pulse-sdk');

exports.handler = function ({ event: body, constants, triggers }, context, callback) {
    function emitEvent(name, payload) {
        let t = triggers.find(t => t.name === name);
        return t && new Webhooks().invoke(t, payload);
    }

    var projectId = body.projectId || constants.QTEST_PROJECT_ID;
    var cycleId = body.testcycle || constants.QTEST_TEST_CYCLE_ID;
    var testLogs = body.logs;
    var MAX_RETRIES = 30;

    var headers = {
        'Content-Type': 'application/json',
        'Authorization': 'bearer ' + constants.QTEST_TOKEN
    };

    request.post({
        url: 'https://' + constants.ManagerURL + '/api/v3/projects/' + projectId + '/auto-test-logs?type=automation',
        json: true,
        headers: headers,
        body: { test_cycle: cycleId, test_logs: testLogs }
    }, function (err, response, resBody) {
        if (err) {
            console.log('[ERROR] Upload failed:', err);
            emitEvent('ChatOpsEvent', { message: '[ERROR] qTest upload failed: ' + err });
            return;
        }

        if (resBody.type === 'AUTOMATION_TEST_LOG') {
            queueId = resBody.id;
            console.log('[INFO] Results queued. ID: ' + queueId);
            emitEvent('ChatOpsEvent', { message: '[INFO] Results queued in qTest. ID: ' + queueId });
            pollQueue(queueId, 0);
        } else {
            console.log('[ERROR] Unexpected response (status ' + response.statusCode + '):', JSON.stringify(resBody));
            emitEvent('ChatOpsEvent', { message: '[ERROR] qTest upload failed. Status: ' + response.statusCode + ' Body: ' + JSON.stringify(resBody) });
        }
    });

    function pollQueue(queueId, attempt) {
        if (attempt >= MAX_RETRIES) {
            console.log('[WARN] Queue polling timed out for ID: ' + queueId);
            emitEvent('ChatOpsEvent', { message: '[WARN] Queue processing timed out' });
            return;
        }

        setTimeout(function () {
            request({
                url: 'https://' + constants.ManagerURL + '/api/v3/projects/queue-processing/' + queueId,
                json: true,
                headers: headers
            }, function (err, response, resBody) {
                if (err) {
                    console.log('[ERROR] Queue check failed:', err);
                    return;
                }

                var state = resBody.state;
                console.log('[INFO] Queue ' + queueId + ' state: ' + state);

                if (state === 'FAILED') {
                    console.log('[ERROR] Queue failed:', resBody.content);
                    emitEvent('ChatOpsEvent', { message: '[ERROR] Queue processing failed: ' + resBody.content });
                } else if (state === 'IN_WAITING' || state === 'IN_PROCESSING' || state === 'PENDING') {
                    pollQueue(queueId, attempt + 1);
                } else {
                    console.log('[SUCCESS] Queue processing complete. State: ' + state);
                    emitEvent('ChatOpsEvent', { message: '[SUCCESS] Test results processed in qTest' });
                    emitEvent('LinkRequirements', body);
                }
            });
        }, 2000);
    }
};

const request = require('request');
const { Webhooks } = require('@qasymphony/pulse-sdk');

exports.handler = function ({ event: body, constants, triggers }, context, callback) {
    function emitEvent(name, payload) {
        let t = triggers.find(t => t.name === name);
        return t && new Webhooks().invoke(t, payload);
    }

    var projectId = body.projectId;
    var testLogs = body.logs;

    var headers = {
        'Content-Type': 'application/json',
        'Authorization': 'bearer ' + constants.QTEST_TOKEN,
        'x-scenario-project-id': constants.SCENARIO_PROJECT_ID
    };

    request.get({
        url: constants.Scenario_URL + '/api/features',
        headers: headers
    }, function (err, response, resBody) {
        if (err) {
            console.log('[ERROR] Failed to get features:', err);
            emitEvent('ChatOpsEvent', { message: '[ERROR] Could not retrieve features: ' + err });
            return;
        }

        var features;
        try {
            features = JSON.parse(resBody);
        } catch (e) {
            console.log('[ERROR] Failed to parse features:', e.message);
            emitEvent('ChatOpsEvent', { message: '[ERROR] Invalid features response' });
            return;
        }

        console.log('[INFO] Retrieved ' + features.length + ' features from Scenario');
        linkTestCasesToRequirements(features);
    });

    function linkTestCasesToRequirements(features) {
        testLogs.forEach(function (testLog) {
            var matching = features.filter(function (f) {
                return f.name === testLog.featureName;
            });

            if (matching.length === 0) {
                console.log('[INFO] No matching feature for: ' + testLog.name);
                return;
            }

            matching.forEach(function (feature) {
                findAndLinkRequirement(feature.issueKey, testLog.name);
            });
        });

        emitEvent('UpdateScenarioSteps', body);
    }

    function findAndLinkRequirement(issueKey, testCaseName) {
        request.post({
            url: 'https://' + constants.ManagerURL + '/api/v3/projects/' + projectId + '/search',
            json: true,
            headers: headers,
            body: {
                object_type: 'requirements',
                fields: ['*'],
                query: "Name ~ '" + issueKey + "'"
            }
        }, function (err, response, reqResult) {
            if (err || !reqResult.items || reqResult.items.length === 0) {
                console.log('[INFO] No requirement found for: ' + issueKey);
                return;
            }

            var reqId = reqResult.items[0].id;

            request.post({
                url: 'https://' + constants.ManagerURL + '/api/v3/projects/' + projectId + '/search',
                json: true,
                headers: headers,
                body: {
                    object_type: 'test-cases',
                    fields: ['*'],
                    query: "Name = '" + testCaseName + "'"
                }
            }, function (tcErr, tcResponse, tcResult) {
                if (tcErr || !tcResult.items || tcResult.items.length === 0) {
                    console.log('[INFO] Test case not yet in qTest: ' + testCaseName);
                    return;
                }

                var tcId = tcResult.items[0].id;

                request.post({
                    url: 'https://' + constants.ManagerURL + '/api/v3/projects/' + projectId + '/requirements/' + reqId + '/link?type=test-cases',
                    json: true,
                    headers: headers,
                    body: [tcId]
                }, function (linkErr) {
                    if (linkErr) {
                        console.log('[ERROR] Link failed:', linkErr);
                        return;
                    }
                    console.log('[SUCCESS] Linked TC "' + testCaseName + '" to requirement "' + issueKey + '"');
                    emitEvent('ChatOpsEvent', { message: '[SUCCESS] Linked: ' + testCaseName + ' -> ' + issueKey });
                });
            });
        });
    }
};

const request = require('request');
const { Webhooks } = require('@qasymphony/pulse-sdk');

exports.handler = function ({ event: body, constants, triggers }, context, callback) {
    function emitEvent(name, payload) {
        var t = triggers.find(function (tr) { return tr.name === name; });
        return t && new Webhooks().invoke(t, payload);
    }

    var testLogs = body.logs;
    if (!testLogs || !Array.isArray(testLogs) || testLogs.length === 0) {
        console.log('[WARN] No test logs provided');
        emitEvent('ChatOpsEvent', { message: ':warning: *Scenario Steps Update*\nNo test logs to process.' });
        return;
    }

    var scenarioURL = constants.Scenario_URL;
    var projectId = constants.SCENARIO_PROJECT_ID;
    var token = constants.QTEST_TOKEN;

    if (!scenarioURL || !projectId || !token) {
        var missing = [];
        if (!scenarioURL) missing.push('Scenario_URL');
        if (!projectId) missing.push('SCENARIO_PROJECT_ID');
        if (!token) missing.push('QTEST_TOKEN');
        console.log('[ERROR] Missing constants: ' + missing.join(', '));
        emitEvent('ChatOpsEvent', {
            message: ':x: *Scenario Steps Update Failed*\nMissing configuration: `' + missing.join('`, `') + '`'
        });
        return;
    }

    scenarioURL = scenarioURL.replace(/\/+$/, '');

    var headers = {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token,
        'x-scenario-project-id': projectId
    };

    var results = { updated: [], failed: [], notFound: [] };

    getAllSteps(scenarioURL, headers).then(function (allSteps) {
        console.log('[INFO] Fetched ' + allSteps.length + ' steps from Scenario');

        if (allSteps.length === 0) {
            console.log('[WARN] No steps found in Scenario project');
            emitEvent('ChatOpsEvent', {
                message: ':warning: *Scenario Steps Update*\nNo steps found in the Scenario project. Verify the project ID.'
            });
            return;
        }

        var promises = [];

        testLogs.forEach(function (log) {
            if (!log.test_step_logs || !Array.isArray(log.test_step_logs)) return;

            log.test_step_logs.forEach(function (step) {
                var name = step.description ? step.description.trim() : '';
                if (!name) return;

                var keyword = step.keyword || '';
                if (keyword === 'Before' || keyword === 'After') return;

                var searchText = name;
                var kwTrimmed = keyword.trim();
                if (kwTrimmed && searchText.startsWith(kwTrimmed + ' ')) {
                    searchText = searchText.slice(kwTrimmed.length + 1);
                }

                var status = step.status ? step.status.toUpperCase() : 'FAILED';
                if (status === 'UNDEFINED') status = 'FAILED';

                var matched = allSteps.filter(function (s) {
                    var textMatch = s.text && s.text.trim() === searchText.trim();
                    if (!textMatch) return false;
                    if (kwTrimmed && s.keyword) {
                        return s.keyword.trim() === kwTrimmed;
                    }
                    return true;
                });

                if (matched.length === 0) {
                    console.log('[WARN] No matching step found for: "' + name + '"');
                    results.notFound.push(name);
                    return;
                }

                matched.forEach(function (s) {
                    var p = updateStep(scenarioURL, headers, s.id, Object.assign({}, s, { status: status }))
                        .then(function () {
                            console.log('[OK] Updated step "' + name + '" -> ' + status);
                            results.updated.push({ name: name, status: status });
                        })
                        .catch(function (err) {
                            var errMsg = err.message || String(err);
                            console.log('[ERROR] Failed to update step "' + name + '":', errMsg);
                            results.failed.push({ name: name, error: errMsg });
                        });
                    promises.push(p);
                });
            });
        });

        return Promise.all(promises);
    })
    .then(function () {
        console.log('[SUCCESS] All scenario steps processed');
        emitEvent('ChatOpsEvent', { message: buildSummary(results) });
    })
    .catch(function (err) {
        var errMsg = err.message || String(err);
        console.log('[ERROR] Step update error:', errMsg);
        emitEvent('ChatOpsEvent', {
            message: ':x: *Scenario Steps Update Failed*\n' + errMsg
        });
    });
};

function buildSummary(results) {
    var icon = results.failed.length > 0 ? ':warning:' : ':white_check_mark:';
    var lines = [];

    lines.push(icon + ' *Scenario Steps Update Summary*');
    lines.push('');

    if (results.updated.length > 0) {
        var byStatus = {};
        results.updated.forEach(function (u) {
            if (!byStatus[u.status]) byStatus[u.status] = [];
            byStatus[u.status].push(u.name);
        });

        Object.keys(byStatus).forEach(function (status) {
            var statusIcon = status === 'PASSED' ? ':large_green_circle:'
                : status === 'FAILED' ? ':red_circle:'
                : ':white_circle:';
            lines.push(statusIcon + ' *' + status + '* (' + byStatus[status].length + ' steps)');
            byStatus[status].forEach(function (name) {
                lines.push('    ' + name);
            });
        });
    }

    if (results.failed.length > 0) {
        lines.push('');
        lines.push(':x: *Update Errors* (' + results.failed.length + ')');
        results.failed.forEach(function (f) {
            lines.push('    ' + f.name + ' \u2014 `' + f.error + '`');
        });
    }

    if (results.notFound.length > 0) {
        lines.push('');
        lines.push(':mag: *Not Found in Scenario* (' + results.notFound.length + ' steps skipped)');
    }

    lines.push('');
    lines.push('*Totals:* ' + results.updated.length + ' updated | '
        + results.failed.length + ' errors | '
        + results.notFound.length + ' not found');

    return lines.join('\n');
}

function getAllSteps(scenarioURL, headers) {
    return new Promise(function (resolve, reject) {
        request({
            url: scenarioURL + '/api/steps',
            method: 'GET',
            headers: headers,
            json: true,
            timeout: 30000
        }, function (err, response, resBody) {
            if (err) {
                if (err.code === 'ETIMEDOUT' || err.code === 'ESOCKETTIMEDOUT') {
                    return reject(new Error('Scenario API timed out fetching steps'));
                }
                return reject(new Error('Scenario API request failed: ' + (err.message || err)));
            }
            if (!response) {
                return reject(new Error('No response received from Scenario API'));
            }
            if (response.statusCode >= 400) {
                var detail = typeof resBody === 'string' ? resBody.substring(0, 200) : JSON.stringify(resBody);
                return reject(new Error('GET /api/steps failed (' + response.statusCode + '): ' + detail));
            }
            resolve(Array.isArray(resBody) ? resBody : []);
        });
    });
}

function updateStep(scenarioURL, headers, stepId, stepData) {
    return new Promise(function (resolve, reject) {
        request({
            url: scenarioURL + '/api/steps/' + stepId,
            method: 'PUT',
            headers: headers,
            json: true,
            body: stepData,
            timeout: 15000
        }, function (err, response, resBody) {
            if (err) {
                if (err.code === 'ETIMEDOUT' || err.code === 'ESOCKETTIMEDOUT') {
                    return reject(new Error('Timeout updating step ' + stepId));
                }
                return reject(new Error('Request failed: ' + (err.message || err)));
            }
            if (!response) {
                return reject(new Error('No response for step ' + stepId));
            }
            if (response.statusCode >= 400) {
                var detail = typeof resBody === 'string' ? resBody.substring(0, 200) : JSON.stringify(resBody);
                return reject(new Error('PUT step ' + stepId + ' failed (' + response.statusCode + '): ' + detail));
            }
            resolve(resBody);
        });
    });
}
